package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.util.*;
public class UsbExtremeTest {
 static int checks;static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}
 static OpticalImage.Source source(byte[] data){return new OpticalImage.Source(){public long size(){return data.length;}public void read(long at,byte[] b,int off,int n)throws IOException{if(at<0||n>data.length-at)throw new IOException("BOUNDS");System.arraycopy(data,(int)at,b,off,n);}public void close(){}};}
 public static void main(String[] args)throws Exception{
 check(UsbExtreme.checksum("Owned Demo")==0xf5e0eb0e,"independent official CRC vector");check(UsbExtreme.checksum("Test")==0x58c3e2ce,"second CRC vector");UsbExtreme.Game g=UsbExtreme.game("Owned Demo","SLUS_123.45",2,0x14);byte[] cfg=g.record();check(cfg.length==64&&cfg[47]==2&&cfg[48]==20&&cfg[53]==8,"standard independent cfg offsets");check(g.part(0).equals("ul.F5E0EB0E.SLUS_123.45.00")&&g.part(1).endsWith(".01"),"standard naming/index");check(UsbExtreme.read(new ByteArrayInputStream(cfg)).get(0).id.equals(g.id),"catalog parse");
 for(String title:new String[]{""," bad","bad ","عنوان","x\n","123456789012345678901234567890123"})try{UsbExtreme.game(title,g.id,1,20);throw new AssertionError("bad title");}catch(IOException expected){checks++;}
 for(byte[] bad:new byte[][]{new byte[0],new byte[63],new byte[64],Arrays.copyOf(cfg,65)})try{UsbExtreme.read(new ByteArrayInputStream(bad));throw new AssertionError("bad cfg");}catch(IOException expected){checks++;}
 byte[] doubleCfg=new byte[128];System.arraycopy(cfg,0,doubleCfg,0,64);System.arraycopy(cfg,0,doubleCfg,64,64);try{UsbExtreme.read(new ByteArrayInputStream(doubleCfg));throw new AssertionError("duplicate cfg");}catch(IOException expected){checks++;}
 Path root=Paths.get("artifacts/usbextreme-fixtures");byte[] iso=Files.readAllBytes(root.resolve("owned.iso"));check(UsbExtreme.discId(source(iso)).equals(g.id),"independent ISO/SYSTEM.CNF parser");for(String bad:new String[]{"ambiguous.iso","missing.iso"})try{UsbExtreme.discId(source(Files.readAllBytes(root.resolve(bad))));throw new AssertionError("bad boot");}catch(IOException expected){checks++;}
 Map<String,ByteArrayOutputStream> files=new HashMap<>();ConsoleParts.Sink sink=new ConsoleParts.Sink(){public OutputStream create(String name)throws IOException{if(files.containsKey(name))throw new IOException("DUPLICATE");ByteArrayOutputStream out=new ByteArrayOutputStream();files.put(name,out);return out;}public void sync(String name){}public InputStream reopen(String name){return new ByteArrayInputStream(files.get(name).toByteArray());}};String report=UsbExtreme.write(source(iso),g.title,"DVD",sink,(a,b)->{});check(report.startsWith(g.id+"\n1\n"),"writer report");check(files.size()==2&&Arrays.equals(files.get(g.part(0)).toByteArray(),iso),"full stream saved part bytes equal independent ISO");byte[] expected=g.record();expected[47]=1;check(Arrays.equals(files.get("ul.cfg").toByteArray(),expected),"catalog independently expected bytes");
 Files.write(root.resolve("ul.cfg"),files.get("ul.cfg").toByteArray());Files.write(root.resolve(g.part(0)),files.get(g.part(0)).toByteArray());
 try{UsbExtreme.write(source(iso),g.title,"DVD",sink,(a,b)->{throw new IOException("CANCELLED");});throw new AssertionError("cancel");}catch(IOException expectedError){check(expectedError.getMessage().equals("CANCELLED"),"cancel");}
 // Virtual >1GiB source/sink exercise the real production part seam without caching a large image.
 final long bigSize=UsbExtreme.PART+2048;OpticalImage.Source big=new OpticalImage.Source(){public long size(){return bigSize;}public void read(long at,byte[] out,int off,int n)throws IOException{if(at<0||n>bigSize-at)throw new IOException("BOUNDS");Arrays.fill(out,off,off+n,(byte)0);if(at<iso.length)System.arraycopy(iso,(int)at,out,off,(int)Math.min(n,iso.length-at));}public void close(){}};Map<String,Long> lengths=new HashMap<>();final byte[][] catalog={null};
 ConsoleParts.Sink virtual=new ConsoleParts.Sink(){public OutputStream create(String name){if(name.equals("ul.cfg"))return new ByteArrayOutputStream(){public void close(){catalog[0]=toByteArray();}};int index=name.endsWith(".00")?0:name.endsWith(".01")?1:-1;if(index<0)throw new AssertionError(name);long start=index*UsbExtreme.PART;return new OutputStream(){long count;byte[] expected=new byte[65536];public void write(int b){throw new AssertionError("stream block expected");}public void write(byte[] b,int off,int n)throws IOException{big.read(start+count,expected,0,n);for(int i=0;i<n;i++)if(expected[i]!=b[off+i])throw new AssertionError("virtual saved bytes");count+=n;}public void close(){lengths.put(name,count);}};}public InputStream reopen(String name){if(name.equals("ul.cfg"))return new ByteArrayInputStream(catalog[0]);long start=name.endsWith(".00")?0:UsbExtreme.PART,end=Math.min(UsbExtreme.PART,bigSize-start);return new InputStream(){long at;public int read(){if(at==end)return -1;throw new AssertionError("block read expected");}public int read(byte[] b,int off,int n)throws IOException{if(at==end)return -1;n=(int)Math.min(n,end-at);big.read(start+at,b,off,n);at+=n;return n;}};}public void sync(String n){}};
 // Permit EOF probes used by writer without accidentally accepting a byte at EOF.
 String bigReport=UsbExtreme.write(big,g.title,"DVD",virtual,(a,b)->{});check(bigReport.startsWith(g.id+"\n2\n"),"real 1GiB seam report");check(lengths.get(g.part(0))==UsbExtreme.PART&&lengths.get(g.part(1))==2048,"production 1GiB/tail boundaries");check(UsbExtreme.read(new ByteArrayInputStream(catalog[0])).get(0).parts==2,"two-part catalog");
 System.out.println("PASS: "+checks+" USBExtreme format/CRC/catalog/ISO/readback/options/cancel assertions");
 }
}
